import{_ as p,o as a,c as t,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/8fb8b24477484c48b2b635efea610cb1.DkAU4y_T.png",i="/bzygq/assets/afb123656e9c42c1b1ae857d56f42d47.Dfk1ayAN.png",o="/bzygq/assets/097964f142ce4c439b40b73009c4cbb1.BSf8AWOA.png",l="/bzygq/assets/08f4daeaf4e443319c9c5c8e4f994ce3.YnM80s9-.png",P=JSON.parse('{"title":"RAG系统架构与Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"AI应用开发/三、RAG教程/RAG系统架构与Pipeline.md","filePath":"AI应用开发/三、RAG教程/RAG系统架构与Pipeline.md","lastUpdated":1788928265000}'),s={name:"AI应用开发/三、RAG教程/RAG系统架构与Pipeline.md"};function d(h,e,A,c,m,b){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="rag系统架构与pipeline" tabindex="-1">RAG系统架构与Pipeline <a class="header-anchor" href="#rag系统架构与pipeline" aria-label="Permalink to &quot;RAG系统架构与Pipeline&quot;">​</a></h1><p><strong>RAG系统架构与Pipeline</strong></p><p>上一节讲 RAG 的核心思想是“先检索，再生成”。这一节要继续往工程实现里走：一个真正可用的 RAG 系统，通常不是在用户提问时临时读文档、临时塞给模型，而是把知识入库、检索召回、上下文构建、模型生成、引用追踪和日志评估组织成一条稳定的 Pipeline。</p><p>所以，理解 RAG 系统架构时，不要只背“文档解析、Embedding、向量库、LLM”这些名词。更重要的是看清楚两件事：第一，知识在离线阶段如何被加工成可检索的结构；第二，用户问题在在线阶段如何一步步变成带依据的答案。RAG 的效果不是由某一个模块单独决定的，而是由这两条链路共同决定的。</p><p>RAG 要分成离线和在线两条链路</p><p>企业知识库问答面对的资料通常很多，可能包括制度文档、产品手册、项目资料、接口文档、工单记录和业务流程说明。如果用户每问一次，系统都重新解析所有文档、重新切分、重新向量化，再去生成答案，成本和延迟都会不可接受。因此，RAG 系统通常会把“知识准备”和“问答生成”拆开。</p><p>离线链路负责把原始资料加工成可检索的知识库。它更像数据工程，重点是解析质量、切分粒度、元数据、权限和索引更新。在线链路负责在用户提问时快速找到相关材料，并把材料组织成模型能使用的上下文。它更像服务编排，重点是检索准确率、响应延迟、Prompt 约束、引用来源和兜底策略。</p><p><img src="'+n+'" alt=""></p><p>这张图要看懂的是职责边界：离线链路决定“知识库里有什么、质量怎么样、能不能被正确检索”；在线链路决定“用户问题来了以后，能不能找准、排好、拼好并回答好”。很多 RAG 项目效果不好，并不是模型能力突然失效，而是这两条链路中某个环节把噪声、缺失或错误传递到了最后。</p><h1 id="二、离线建库-把文档变成可检索的知识单元" tabindex="-1">二、离线建库：把文档变成可检索的知识单元 <a class="header-anchor" href="#二、离线建库-把文档变成可检索的知识单元" aria-label="Permalink to &quot;二、离线建库：把文档变成可检索的知识单元&quot;">​</a></h1><p>离线建库的目标不是简单地把文档存进数据库，而是把原始资料加工成适合检索、适合追溯、适合权限控制的知识单元。这个过程通常从文档接入开始，经过解析、清洗、切分、元数据补全、Embedding 和索引写入，最后形成可以被在线问答调用的检索底座。</p><p><img src="'+i+'" alt=""></p><p>文档解析是第一道质量关。PDF、Word、网页、Markdown、Excel 等资料表面上都是“文档”，但结构差异很大。PDF 可能有页眉页脚、分栏、扫描图片和复杂表格；Word 可能有标题层级、批注和嵌套表格；网页可能混入导航栏、广告和脚本残留。如果解析阶段把章节顺序打乱、表格关系拆散、页眉页脚当成正文，后面的向量检索会把这些噪声一起召回。</p><p>清洗和结构化的作用，是让文档从“能读取的文本”变成“能理解的知识”。这一层通常会处理多余空行、重复页眉、目录页、免责声明、无意义符号，也会尽量保留标题层级、段落归属、表格标题和图片说明。RAG 不是只靠向量相似度工作，很多时候章节标题、文档类型、创建时间、业务线、权限范围这些元数据会直接影响检索过滤和引用展示。</p><p>Chunk 切分是离线链路里最容易被低估的环节。切得太大，一个片段里可能混进多个主题，召回后模型拿到的信息不够聚焦；切得太小，语义上下文被切断，模型只看到半句话或缺少前因后果。实际项目里常见做法是按标题、段落、语义边界和长度窗口综合切分，并为相邻片段保留一定 overlap，让一个知识点不会因为边界问题被硬切开。</p><p>Embedding 和向量入库解决的是“如何让语义相近的内容可以被找出来”。系统会把每个 Chunk 转成向量，同时保存原文、标题、来源、章节、权限、版本、时间等字段。注意，向量库不是只存向量的地方，它通常还承担过滤、索引、召回和元数据查询。没有元数据的向量库，很难做企业级权限隔离，也很难给用户展示可信引用。</p><h1 id="三、在线问答-把用户问题变成带依据的答案" tabindex="-1">三、在线问答：把用户问题变成带依据的答案 <a class="header-anchor" href="#三、在线问答-把用户问题变成带依据的答案" aria-label="Permalink to &quot;三、在线问答：把用户问题变成带依据的答案&quot;">​</a></h1><p>在线链路从用户问题开始，但用户输入通常并不适合直接检索。用户可能会说“报销怎么弄”“这个能走特批吗”“上次那个接口超时怎么处理”，这些问题短、口语化、上下文依赖强。RAG 系统需要先理解问题，再决定如何检索。</p><p><img src="'+o+'" alt=""></p><p>问题预处理常见包括意图识别、查询改写、关键词补全和多轮上下文合并。例如用户问“这个能不能特批”，系统需要结合当前会话或业务入口判断“这个”指的是什么，再把问题改写成更适合检索的表达。这个环节做得不好，后面向量检索就会从一开始偏离方向。</p><p>召回阶段会根据问题向量、关键词、元数据过滤等方式找出候选片段。只用向量检索容易漏掉精确编号、专有名词和制度条款；只用关键词检索又容易错过语义相近的表达。因此，很多企业 RAG 会采用混合检索，把向量召回、关键词召回和元数据过滤结合起来，再把候选结果送入重排模型。</p><p>Rerank 的作用，是从“可能相关”里挑出“最应该放进上下文”的材料。初步召回的 Top-K 只是候选集合，不代表每个片段都适合给模型。重排会重新评估问题和片段之间的相关性，然后选择更少、更准的 Top-N 放进 Prompt。这里要理解一个工程事实：上下文窗口不是垃圾桶，塞得越多不一定越好。无关材料会增加成本，也会干扰模型判断。</p><p>答案生成阶段并不是让模型自由发挥，而是把用户问题、检索材料、系统约束、输出格式和引用要求组织成一个 Prompt。模型最终回答的质量，既取决于材料是否找对，也取决于 Prompt 是否明确告诉模型“只能基于材料回答、无法确认时要说明资料不足、回答后要给出引用来源”。</p><p>构建：RAG 里的上下文不是简单拼接</p><p>RAG Prompt 的核心任务，是把检索结果变成模型可以稳定使用的证据环境。很多初学者会把 Prompt 构建理解成字符串拼接：前面放几段资料，后面放用户问题，然后让模型回答。这个做法能跑通 Demo，但在真实系统里很容易出现引用混乱、答案越界、材料冲突和无法回答时强行编造。</p><p>一个更稳妥的 Prompt 通常会包含四类信息。第一类是角色和边界，告诉模型它是知识库问答助手，只能基于资料回答。第二类是参考材料，并且每段材料要带来源编号、文档标题、章节、片段内容和必要的元数据。第三类是用户问题和会话背景，保留用户真实意图。第四类是输出约束，例如必须输出结论、依据、引用来源，资料不足时必须明确说明。</p><table tabindex="0"><thead><tr><th>Plain Text你是企业知识库问答助手。请只基于参考资料回答用户问题，不要编造资料中没有的信息。如果资料不足，请回答“当前资料不足，无法确认”，并说明缺少哪类信息。参考资料：[资料1] 标题：费用报销制度 / 章节：差旅报销内容：...[资料2] 标题：审批权限说明 / 章节：特批流程内容：...用户问题：...输出要求：1. 先给出结论；2. 再说明依据；3. 最后列出引用来源编号。</th></tr></thead></table><p>这个模板的重点不在于句子固定，而在于约束关系明确：模型回答必须和材料绑定，引用必须能回到来源，无法确认时不能用经验补齐。对于企业应用来说，这种约束比“回答得像不像人”更重要，因为用户需要知道答案从哪里来、能不能追溯、出了问题怎么排查。</p><p>RAG 系统模块</p><p>从后端开发角度看，RAG 项目不是一个孤立算法，而是一套业务系统。文档管理要处理上传、版本、分类、删除和权限；解析服务要处理文件抽取、OCR、表格和清洗；向量化服务要处理批量任务、失败重试和模型调用成本；检索服务要处理索引、过滤、召回和重排；问答服务要处理会话、Prompt、模型调用和答案流式返回；日志审计要记录问题、召回片段、模型输出、用户反馈和人工复核结果。</p><p><img src="'+l+'" alt=""></p><p>这也是为什么后端同学转 AI 应用开发时，不应该把能力边界理解成“只会调模型接口”。企业 RAG 的难点往往不在于把 API 调通，而在于把文档、权限、检索、模型、日志和评测接成一条可维护的工程链路。一个系统能不能长期使用，取决于它能否持续更新知识、控制权限、定位问题、评估效果，并在错误发生时留下足够证据。</p><h1 id="六、常见架构误区与排查顺序" tabindex="-1">六、常见架构误区与排查顺序 <a class="header-anchor" href="#六、常见架构误区与排查顺序" aria-label="Permalink to &quot;六、常见架构误区与排查顺序&quot;">​</a></h1><p>第一个误区，是以为“用了向量数据库就是 RAG”。向量数据库只是检索组件，不能代表完整系统。没有文档解析、Chunk 策略、元数据、Prompt 约束、引用来源和评估闭环，向量库只能说明系统有召回能力，不能说明系统能稳定回答问题。</p><p>第二个误区，是把所有文档一次性塞进上下文。这样不仅成本高、速度慢，还会让模型在无关材料里摇摆。RAG 的关键不是“给模型更多材料”，而是“给模型更相关、更干净、更可追溯的材料”。</p><p>第三个误区，是只看最终回答，不看召回材料。排查 RAG 问题时，应该先看用户问题被改写成了什么，再看召回片段是否来自正确文档、是否命中正确章节、是否被 Rerank 排到前面。如果召回材料都不对，后面换更强的模型也很难救。</p><p>第四个误区，是没有日志和评估。企业 RAG 上线后，需要记录问题、检索结果、重排结果、最终答案、引用来源、用户反馈和人工审核结果。没有这些记录，系统只能靠主观感受优化，很难定位是解析问题、切分问题、召回问题、Prompt 问题还是模型问题。</p><h1 id="七、面试表达模板" tabindex="-1">七、面试表达模板 <a class="header-anchor" href="#七、面试表达模板" aria-label="Permalink to &quot;七、面试表达模板&quot;">​</a></h1><p>面试中可以这样概括 RAG 架构：</p><table tabindex="0"><thead><tr><th>Plain Text我会把 RAG 系统分成离线建库和在线问答两条链路。离线链路负责文档接入、解析清洗、Chunk 切分、元数据补全、Embedding 和向量入库；在线链路负责问题预处理、混合检索、Top-K 召回、Rerank、Prompt 构建和 LLM 生成。这样设计的好处是知识可以提前加工和持续更新，用户提问时只需要走检索和生成链路，既能控制延迟，也能通过引用来源提升答案可信度。</th></tr></thead></table><p>如果被追问“哪里最容易出问题”，可以继续补充：</p><table tabindex="0"><thead><tr><th>Plain Text我会优先看召回结果，因为 RAG 的回答上限由检索质量决定。如果文档解析丢结构、Chunk 切分不合理、元数据缺失、Embedding 不适配业务语料，或者 Rerank 没有把真正相关的片段排到前面，模型拿到的依据就会不准确。这种情况下，单纯优化 Prompt 或更换大模型通常只能缓解，不能从根上解决问题。</th></tr></thead></table><p>下一篇继续看离线建库里最容易被低估的一层：文档解析、Chunk 切分和 Metadata 设计。</p>',43)])])}const _=p(s,[["render",d]]);export{P as __pageData,_ as default};
